package com.bank.tenure;

import java.util.*;
import java.util.logging.*;

public class TenureDemo {
    private static final Logger log = Logger.getLogger("Tenure");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee("Rajesh", "Trading", 2015),
            new Employee("Rohit", "Trading", 2012),   // longest-serving in Trading
            new Employee("Sneha", "Trading", 2016),
            new Employee("Priya", "Risk", 2018));
        TenureService service = new TenureService();

        service.longestServing(employees, "Trading")
            .ifPresent(e -> log.info(() -> "Longest-serving Trading (findFirst): " + e.getName()));
        service.anyInDepartment(employees, "Trading")
            .ifPresent(e -> log.info(() -> "Any Trading (findAny): " + e.getName()));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final int year;
    Employee(String name, String department, int year) {
        this.name = name; this.department = department; this.year = year;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    int getYear() { return year; }
}

// ─── Would be in service/TenureService.java ───
class TenureService {
    // findFirst on an ORDERED (sorted) stream → deterministic earliest joiner
    Optional<Employee> longestServing(List<Employee> employees, String dept) {
        return employees.stream()
            .filter(e -> e.getDepartment().equals(dept))
            .sorted(Comparator.comparingInt(Employee::getYear)) // earliest year first
            .findFirst();
    }

    // findAny → any representative, cheapest in parallel (existence check)
    Optional<Employee> anyInDepartment(List<Employee> employees, String dept) {
        return employees.stream()
            .filter(e -> e.getDepartment().equals(dept))
            .findAny();
    }
}
